export const bookingsRelations = relations(bookings, ({one, many}) => ({
	hotel: one(hotels, {
		fields: [bookings.hotelId],
		references: [hotels.id]
	}),
	customer: one(customers, {
		fields: [bookings.customerId],
		references: [customers.id]
	}),
	agent: one(users, {
		fields: [bookings.agentId],
		references: [users.id]
	}),
	bookingRooms: many(bookingRooms),
	guests: many(bookingGuests),
	services: many(bookingServices),
	statusHistory: many(bookingStatusHistory),
	payments: many(payments),
	invoices: many(invoices),
	commissions: many(commissions),
}));

export const bookingRoomsRelations = relations(bookingRooms, ({one}) => ({
	booking: one(bookings, {
		fields: [bookingRooms.bookingId],
		references: [bookings.id]
	}),
	room: one(rooms, {
		fields: [bookingRooms.roomId],
		references: [rooms.id]
	}),
	roomType: one(roomTypes, {
		fields: [bookingRooms.roomTypeId],
		references: [roomTypes.id]
	}),
	user_checkedInById: one(users, {
		fields: [bookingRooms.checkedInById],
		references: [users.id],
		relationName: "bookingRooms_checkedInById_users_id"
	}),
	user_checkedOutById: one(users, {
		fields: [bookingRooms.checkedOutById],
		references: [users.id],
		relationName: "bookingRooms_checkedOutById_users_id"
	}),
}));

