export const commissionsRelations = relations(commissions, ({one}) => ({
	// Named `agent`, not `user`: introspection names a relation after the target
	// table, but the API has always returned this as `agent` and the admin UI
	// reads commission.agent.
	agent: one(users, {
		fields: [commissions.agentId],
		references: [users.id]
	}),
	booking: one(bookings, {
		fields: [commissions.bookingId],
		references: [bookings.id]
	}),
}));

